From bc0cb56f055f2cfc1a6f54685bb6f8f948cf4f20 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:40:31 +0100
Subject: [PATCH] shell: separate print() outputs of evaluateScript with
 newlines

evaluateScript appended every print() and error message to the reply
with no separator, so successive prints came back run together. Collect
the messages instead and join them with newlines in the returned text.

BUG: 524520
---
 shell/shellcorona.cpp | 15 ++++++---------
 1 file changed, 6 insertions(+), 9 deletions(-)

diff --git a/shell/shellcorona.cpp b/shell/shellcorona.cpp
index 51bde18ac6..3b9580fdbc 100644
--- a/shell/shellcorona.cpp
+++ b/shell/shellcorona.cpp
@@ -2008,28 +2008,25 @@ QString ShellCorona::evaluateScript(const QString &script)
     }

     WorkspaceScripting::ScriptEngine scriptEngine(this);
-    QString buffer;
-    QTextStream bufferStream(&buffer, QIODevice::WriteOnly | QIODevice::Text);
+    QStringList output;

-    connect(&scriptEngine, &WorkspaceScripting::ScriptEngine::printError, this, [&bufferStream](const QString &msg) {
+    connect(&scriptEngine, &WorkspaceScripting::ScriptEngine::printError, this, [&output](const QString &msg) {
         qCWarning(PLASMASHELL) << msg;
-        bufferStream << msg;
+        output << msg;
     });
-    connect(&scriptEngine, &WorkspaceScripting::ScriptEngine::print, this, [&bufferStream](const QString &msg) {
+    connect(&scriptEngine, &WorkspaceScripting::ScriptEngine::print, this, [&output](const QString &msg) {
         qCDebug(PLASMASHELL) << msg;
-        bufferStream << msg;
+        output << msg;
     });

     scriptEngine.evaluateScript(script);

-    bufferStream.flush();
-
     if (calledFromDBus() && !scriptEngine.errorString().isEmpty()) {
         sendErrorReply(QDBusError::Failed, scriptEngine.errorString());
         return {};
     }

-    return buffer;
+    return output.join(u'\n');
 #else
     Q_UNUSED(script)
     return QString();
-- 
